async function solve(maxAttempts, succeedAt) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    await new Promise((resolve) => setTimeout(resolve, 5));
    if (attempt >= succeedAt) return attempt;
  }
  throw new Error("Wyczerpano próby");
}

function solve(products, viewState) {
  const query = viewState.currentQuery.trim().toLowerCase();
  const filtered = products.filter((product) => {
    const matchesQuery = product.name.toLowerCase().includes(query);
    const matchesCategory = viewState.currentCategory === "all" || product.category === viewState.currentCategory;
    return matchesQuery && matchesCategory;
  });
  const { key, direction } = viewState.currentSort;
  const factor = direction === "desc" ? -1 : 1;
  const sorted = [...filtered].sort((a, b) => {
    if (key === "price") return (a.price - b.price) * factor;
    return String(a[key]).localeCompare(String(b[key]), "pl") * factor;
  });
  const start = (viewState.currentPage - 1) * viewState.pageSize;
  return sorted.slice(start, start + viewState.pageSize).map((product) => product.name);
}
